def predict(board, action):
    if action[0] < 0 or action[0] >= 64 or action[1] < 0 or action[1] >= 64:
        return board  # Invalid move, return original board

    row, col = action[0], action[1]
    old_char = board[row][col]

    if old_char != 'W':
        return board  # Only 'W' cells can be changed

    new_char = 'G'  # Replace 'W' with 'G'

    board[row][col] = new_char  # Update the board

    return [list(row) for row in board]  # Return the updated board as a list of strings
